SELECT a.ownerUser, count(a.leadId) AS count FROM ( SELECT IFNULL(sl.owner_user, sl.create_by) AS ownerUser, sl.id as leadId FROM sale_lead sl LEFT JOIN customer_info ci ON ci.lead_id = sl.id WHERE 1=1 AND sl.deleted = 0 AND EXISTS ( SELECT 1 FROM customer_company cc WHERE cc.customer_id = ci.id AND ( cc.is_verify_tax = 1 OR cc.is_invoicing = 1) ) AND EXISTS ( SELECT 1 FROM orders o WHERE o.customer_id = ci.id AND o.status = 'PAID' AND o.order_type = 'NORMAL' ) AND sl.tenant_id = #{params.tenantId}
AND COALESCE(NULLIF(sl.owner_user, ''), sl.create_by) IN
#{item}
AND sl.source = #{params.source}
AND sl.create_time >= #{params.start}
AND sl.create_time <= #{params.end}
) a GROUP BY a.ownerUser

