SELECT
    ci.owner_user AS ownerUser,
    count(ci.id) AS count
FROM customer_info ci
WHERE ci.customer_type = 1
AND EXISTS (
    SELECT 1 FROM customer_company cc
    WHERE cc.customer_id = ci.id AND ( cc.is_verify_tax = 1 OR cc.is_invoicing = 1)
)
AND EXISTS (
    SELECT 1 FROM orders o
    WHERE o.customer_id = ci.id AND o.status = 'PAID' AND o.order_type = 'NORMAL'
)

    AND ci.tenant_id = #{params.tenantId}


    AND COALESCE(NULLIF(ci.owner_user, ''), ci.create_by) IN

        #{item}



    AND ci.source = #{params.source}


    AND ci.create_time >= #{params.start}


    AND ci.create_time <= #{params.end}

GROUP BY ci.owner_user

SELECT
    a.ownerUser AS ownerUser,
    -- 全部数据
    SUM( a.unitPrice * a.quantity) AS allPayment,
    count(a.orderDetailId) AS allCount,
    -- 本年度
    SUM(CASE WHEN a.payTime >= #{params.yearStart}
    AND a.payTime <= #{params.yearEnd}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS yearPayment,
    SUM(CASE WHEN a.payTime >= #{params.yearStart}
    AND a.payTime <= #{params.yearEnd}
    THEN 1 ELSE 0 END) AS yearCount,
    -- 本季度
    SUM(CASE WHEN a.payTime >= #{params.quarterStart}
    AND a.payTime <= #{params.quarterEnd}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS quarterPayment,
    SUM(CASE WHEN a.payTime >= #{params.quarterStart}
    AND a.payTime <= #{params.quarterEnd}
    THEN 1 ELSE 0 END) AS quarterCount,
    -- 上月
    SUM(CASE WHEN a.payTime >= #{params.lastMonthStart}
    AND a.payTime <= #{params.lastMonthEnd}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS lastMonthPayment,
    SUM(CASE WHEN a.payTime >= #{params.lastMonthStart}
    AND a.payTime <= #{params.lastMonthEnd}
    THEN 1 ELSE 0 END) AS lastMonthCount,
    -- 本月
    SUM(CASE WHEN a.payTime >= #{params.monthStart}
    AND a.payTime <= #{params.monthEnd}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS monthPayment,
    SUM(CASE WHEN a.payTime >= #{params.monthStart}
    AND a.payTime <= #{params.monthEnd}
    THEN 1 ELSE 0 END) AS monthCount,
    -- 今日数据（2025-12-15）
    SUM(CASE WHEN DATE(a.payTime) = #{params.today}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS todayPayment,
    SUM(CASE WHEN DATE(a.payTime) = #{params.today}
    THEN 1 ELSE 0 END) AS todayCount,
    -- 昨日数据（2025-12-14）
    SUM(CASE WHEN DATE(a.payTime) = #{params.yesterday}
    THEN a.unitPrice * a.quantity ELSE 0 END) AS yesterdayPayment,
    SUM(CASE WHEN DATE(a.payTime) = #{params.yesterday}
    THEN 1 ELSE 0 END) AS yesterdayCount
FROM (
    SELECT
        IFNULL(ci.owner_user, ci.create_by) AS ownerUser,
        od.id AS orderDetailId,
        od.unit_price AS unitPrice,
        od.quantity AS quantity,
        o.pay_time AS payTime
    FROM order_details od
    LEFT JOIN orders o ON od.order_id = o.id
    LEFT JOIN customer_info ci ON o.customer_id = ci.id
    WHERE 1=1
    AND o.order_type = 'NORMAL'
    AND o.status = 'PAID'
    AND od.product_id NOT IN (38)

        AND ci.tenant_id = #{params.tenantId}


        AND COALESCE(NULLIF(ci.owner_user, ''), ci.create_by) IN

            #{item}


) a
GROUP BY a.ownerUser

SELECT a.ownerUser, count(orderDetailId) AS count FROM ( SELECT IFNULL(sl.owner_user, sl.create_by) AS ownerUser, od.id as orderDetailId FROM sale_lead sl INNER JOIN customer_info ci ON ci.lead_id = sl.id LEFT JOIN orders o ON o.customer_id = ci.id LEFT JOIN order_details od ON od.order_id = o.id WHERE sl.deleted = 0 AND o.order_type = 'NORMAL' AND o.status = 'PAID' AND od.product_id NOT IN (38)
AND sl.tenant_id = #{params.tenantId}
AND COALESCE(NULLIF(sl.owner_user, ''), sl.create_by) IN
#{item}
AND sl.source = #{params.source}
AND sl.create_time >= #{params.start}
AND sl.create_time <= #{params.end}
) a GROUP BY a.ownerUser
